// Build CSS custom properties from the DTCG design tokens owned by bao-design.
// Input:  ../design/tokens/{base,color.light,color.dark}.tokens.json
// Output: src/generated/tokens.css  (generated, git-ignored, do not edit); `--out <path>` (relative to the cwd)
//         lets site/ reuse the same tokens without a second copy.
// Deliberately dependency-free (no Style Dictionary) to keep the supply chain small.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const tokensDir = resolve(here, "../../design/tokens");
const outArg = process.argv.indexOf("--out");
const outFile =
  outArg > 0 && process.argv[outArg + 1]
    ? resolve(process.argv[outArg + 1])
    : resolve(here, "../src/generated/tokens.css");

const load = (name) => JSON.parse(readFileSync(resolve(tokensDir, `${name}.tokens.json`), "utf8"));

/** Flatten a DTCG tree into [["color.text.primary", token], ...]. */
export function flatten(tree, prefix = []) {
  const out = [];
  for (const [key, value] of Object.entries(tree)) {
    if (key.startsWith("$") || value === null || typeof value !== "object") continue;
    const path = [...prefix, key];
    if ("$value" in value) out.push([path.join("."), value]);
    else out.push(...flatten(value, path));
  }
  return out;
}

const cssName = (path) => `--${path.replaceAll(".", "-").replaceAll("_", "-")}`;

/** Serialize one token value; `{a.b}` aliases become var(--a-b). */
export function toCss(token) {
  const v = token.$value;
  if (typeof v === "string") {
    const alias = /^\{([^}]+)\}$/.exec(v);
    if (alias?.[1]) return `var(${cssName(alias[1])})`;
    return v;
  }
  if (typeof v === "number") return String(v);
  if (Array.isArray(v)) return v.map((f) => (/[\s,]/.test(f) ? `"${f}"` : f)).join(", ");
  if (v && typeof v === "object" && "value" in v && "unit" in v) return `${v.value}${v.unit}`;
  throw new Error(`Unsupported token value: ${JSON.stringify(v)}`);
}

const block = (selector, entries) =>
  `${selector} {\n${entries.map(([p, t]) => `  ${cssName(p)}: ${toCss(t)};`).join("\n")}\n}\n`;

function main() {
  const base = flatten(load("base"));
  const light = flatten(load("color.light"));
  const dark = flatten(load("color.dark"));
  const css = [
    "/* GENERATED by scripts/build-tokens.mjs from design/tokens — do not edit. */\n",
    block(":root", [...base, ...light]),
    // Dark: follow the OS unless the user forced light; explicit data-theme="dark" always wins.
    `@media (prefers-color-scheme: dark) {\n${block(':root:not([data-theme="light"])', dark)}}\n`,
    block(':root[data-theme="dark"]', dark),
  ].join("\n");
  mkdirSync(dirname(outFile), { recursive: true });
  writeFileSync(outFile, css);
  console.log(`tokens: ${base.length + light.length} light, ${dark.length} dark → ${outFile}`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main();
